//autogenerated:yes
//nolint:revive,govet,errcheck
package avssuas_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/avssuas"
	"github.com/stretchr/testify/require"
)

func TestEnum_MAV_AVSS_COMMAND_FAILURE_REASON(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_AVSS_COMMAND_FAILURE_REASON
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.PRS_NOT_STEADY.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_AVSS_COMMAND_FAILURE_REASON
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.PRS_NOT_STEADY, dec)
	})
}
